-- atf_facilities: transitional facility reference (source sheet dated 13 May 2026)
create table if not exists public.atf_facilities (
  atf_code integer primary key,
  status text,
  facility text not null,
  address text,
  city text,
  updated_at timestamptz not null default now()
);
alter table public.atf_facilities enable row level security;
create policy atf_read on public.atf_facilities for select using (is_staff());

